const agentOutput = $input.item.json;
const triggerData = $('Execute Workflow Trigger').item.json;

const WORKFLOW_ID = 'P8NecHn00l4qArkW';
const timestamp = new Date().toISOString();

const hasNodeError = agentOutput.error != null;
let parsed = null;
let parseError = null;

if (!hasNodeError) {
  try {
    const raw = (agentOutput.output || '').trim()
      .replace(/^```json\s*/i, '')
      .replace(/^```\s*/i, '')
      .replace(/\s*```$/i, '');
    parsed = JSON.parse(raw);
  } catch (e) {
    parseError = e.message;
  }
}

if (hasNodeError || parseError) {
  return {
    json: {
      status: 'error',
      execution_metadata: {
        workflow_id: WORKFLOW_ID,
        timestamp,
        source: 'n8n_presale_processor'
      },
      summary: hasNodeError
        ? `Agent execution failed: ${String(agentOutput.error)}`
        : `Failed to parse agent JSON response: ${parseError}`,
      data_type: 'error',
      payload: null,
      extracted_facts: [],
      next_steps: [],
      errors: [{
        code: hasNodeError ? 'AGENT_ERROR' : 'PARSE_ERROR',
        message: hasNodeError ? String(agentOutput.error) : parseError,
        raw_output: hasNodeError ? null : (agentOutput.output || null)
      }]
    }
  };
}

const agentError = parsed.error || null;

return {
  json: {
    status: agentError ? 'error' : 'success',
    execution_metadata: {
      workflow_id: WORKFLOW_ID,
      timestamp,
      source: 'n8n_presale_processor'
    },
    summary: parsed.summary || '',
    data_type: agentError ? 'error' : (parsed.data_type || 'unknown'),
    payload: agentError ? null : (parsed.payload ?? null),
    extracted_facts: parsed.extracted_facts || [],
    next_steps: parsed.next_steps || [],
    errors: agentError ? [agentError] : []
  }
};
